window.kbPageData["views/entry/k-a74be79a48188b75"] = {"key":"entry/k-a74be79a48188b75","state":{"route":"entry/k-a74be79a48188b75"},"node":{"id":"k-a74be79a48188b75","mode":"k","title":"建党 105 周年","type":"事实与事件","domain":"历史","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["历史"],"时间索引":["年度事件或数据"],"来源主题":["重要周年"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"建党 105 周年","slug":"bfe14a41692f"}],"directorySummary":"考点一 建党 105 周年\n2026 年是中国共产党成立 105 周年。1921 年中共一大召开，中国共产党应运而生。2026 年同\n时是“十五五”开局之年，中央纪委五次全会公报、政治局常委会会议均强调做好建党 105 周\n年各项工作。党的二十届四中全会部署的“十五五”规划目标任务，是党领导人民接续…","sources":[{"id":"01fc438f2792500c","label":"建党 105 周年","topic":"重要周年","category":"时政","text":"考点一 建党 105 周年\n2026 年是中国共产党成立 105 周年。1921 年中共一大召开，中国共产党应运而生。2026 年同\n时是“十五五”开局之年，中央纪委五次全会公报、政治局常委会会议均强调做好建党 105 周\n年各项工作。党的二十届四中全会部署的“十五五”规划目标任务，是党领导人民接续奋斗、\n以中国式现代化全面推进强国建设民族复兴伟业的接续篇章。\n时间   1921 年 7 月 23 日至 31 日\n地点   上海，大会最后一天转移到浙江嘉兴南湖\n13 名代表+2 名共产国际代表，陈独秀和李大钊因事务繁忙未出席会议\n13 名代表：李达、李汉俊（上海）；张国焘、刘仁静（北京）；毛泽东、何叔衡（长\n参会\n沙）；董必武、陈潭秋（武汉）；王尽美、邓恩铭（济南）；陈公博（广州）；周佛海\n人物\n（旅日）。包惠僧（广州）受陈独秀派遣，出席了会议。\n2 名共产国际代表：马林、尼克尔斯基。\n党的名称为“中国共产党”（最早由蔡和森提出）\n党的性质是无产阶级政党\n确定\n主要            党的奋斗目标是社会主义和共产主义\n内容            党在当前的任务是组织工人阶级，开展工人运动\n选举       陈独秀为书记，张国焘为组织主任，李达为宣传主任\n通过       党的第一个纲领和党的工作决议\n历史\n党的一大的召开标志着中国共产党的成立\n意义","source":{"doc":"4e539a366dce19555ccf","first":30,"last":30,"page":30,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-a74be79a48188b75":[]}};
